import{_ as a,o,c as i,a2 as s}from"./chunks/framework.CgxQ0r6v.js";const g=JSON.parse('{"title":"Contenido Programático: Bases de Datos (Trayecto II)","description":"","frontmatter":{},"headers":[],"relativePath":"materias/Bases_de_Datos/Contenido_Programatico.md","filePath":"materias/Bases_de_Datos/Contenido_Programatico.md"}'),d={name:"materias/Bases_de_Datos/Contenido_Programatico.md"};function n(r,e,l,t,c,u){return o(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="contenido-programatico-bases-de-datos-trayecto-ii" tabindex="-1">Contenido Programático: Bases de Datos (Trayecto II) <a class="header-anchor" href="#contenido-programatico-bases-de-datos-trayecto-ii" aria-label="Permalink to &quot;Contenido Programático: Bases de Datos (Trayecto II)&quot;">​</a></h1><p><strong>Institución:</strong> Universidad Politécnica Territorial del Estado Trujillo &quot;Mario Briceño Iragorry&quot; (UPTTMBI)<br><strong>Programa:</strong> Programa Nacional de Formación en Informática (PNFI)<br><strong>Unidad Curricular:</strong> Bases de Datos<br><strong>Trayecto:</strong> II<br><strong>Trimestre:</strong> V (Segundo Trimestre del Trayecto II)<br><strong>Tipo:</strong> Curso<br><strong>Unidades Crédito (UC):</strong> 3<br><strong>Código:</strong> BDC213<br><strong>Densidad Horaria:</strong></p><ul><li>Horas de Trabajo del Estudiante Acompañado (HTEA): 5 horas semanales</li><li>Horas de Trabajo de Estudio Independiente (HTEI): 2 horas semanales</li><li>Total Horas de Trabajo del Estudiante (THTE): 7 horas semanales (84 horas por trimestre)</li></ul><hr><h2 id="🎯-proposito-general" tabindex="-1">🎯 PROPÓSITO GENERAL <a class="header-anchor" href="#🎯-proposito-general" aria-label="Permalink to &quot;🎯 PROPÓSITO GENERAL&quot;">​</a></h2><p>Dotar al estudiante de los fundamentos teóricos, metodológicos y prácticos necesarios para concebir, modelar, normalizar, implementar y consultar bases de datos relacionales robustas, garantizando la integridad, consistencia y seguridad de la información como soporte fundamental para el desarrollo de aplicaciones y proyectos sociotecnológicos comunitarios.</p><hr><h2 id="🔌-saberes-y-contenido-analitico" tabindex="-1">🔌 SABERES Y CONTENIDO ANALÍTICO <a class="header-anchor" href="#🔌-saberes-y-contenido-analitico" aria-label="Permalink to &quot;🔌 SABERES Y CONTENIDO ANALÍTICO&quot;">​</a></h2><h3 id="unidad-1-el-mundo-de-las-bases-de-datos-y-los-sistemas-manejadores-de-base-de-datos-smbd-dbms" tabindex="-1">Unidad 1: El mundo de las bases de datos y los sistemas manejadores de base de datos (SMBD / DBMS) <a class="header-anchor" href="#unidad-1-el-mundo-de-las-bases-de-datos-y-los-sistemas-manejadores-de-base-de-datos-smbd-dbms" aria-label="Permalink to &quot;Unidad 1: El mundo de las bases de datos y los sistemas manejadores de base de datos (SMBD / DBMS)&quot;">​</a></h3><ul><li><strong>Conceptos Fundamentales:</strong><ul><li>Definición de datos, información y sistema de base de datos.</li><li>Limitaciones del procesamiento de archivos tradicionales (redundancia, inconsistencia, dificultad de acceso, aislamiento).</li><li>Concepto de Sistema Manejador de Bases de Datos (SMBD / DBMS).</li><li>Evolución histórica de los modelos de bases de datos (Jerárquico, Red, Relacional, NoSQL y Nuevas Tendencias).</li></ul></li><li><strong>Arquitectura y Componentes de un DBMS:</strong><ul><li>Niveles de Abstracción de Datos (Arquitectura ANSI/SPARC de 3 niveles: Físico, Conceptual y Externo).</li><li>Independencia de datos: Física y Lógica.</li><li>Componentes del motor de base de datos: Procesador de consultas, Gestor de transacciones, Gestor de almacenamiento y Diccionario de datos.</li><li>Lenguajes de bases de datos: Lenguaje de Definición de Datos (DDL) y Lenguaje de Manipulación de Datos (DML).</li></ul></li><li><strong>Arquitecturas de Sistemas de Bases de Datos:</strong><ul><li>Arquitectura Centralizada.</li><li>Arquitectura Cliente–Servidor (2 capas).</li><li>Arquitectura Multicapas (3 o más capas: Cliente Web/Móvil, Servidor de Aplicaciones, Servidor de Base de Datos).</li></ul></li><li><strong>Administración de Bases de Datos:</strong><ul><li>Definición y roles del Administrador de Bases de Datos (DBA) y Administrador de Datos (DA).</li><li>Responsabilidades críticas: Diseño físico, seguridad y control de acceso, respaldo y recuperación (Backup/Restore), monitorización y afinación de rendimiento.</li></ul></li></ul><h3 id="unidad-2-elementos-para-interpretar-y-disenar-el-modelo-conceptual-de-datos-e-r-y-mermaid-erd" tabindex="-1">Unidad 2: Elementos para interpretar y diseñar el modelo conceptual de datos (E/R y Mermaid ERD) <a class="header-anchor" href="#unidad-2-elementos-para-interpretar-y-disenar-el-modelo-conceptual-de-datos-e-r-y-mermaid-erd" aria-label="Permalink to &quot;Unidad 2: Elementos para interpretar y diseñar el modelo conceptual de datos (E/R y Mermaid ERD)&quot;">​</a></h3><ul><li><strong>Fundamentos del Modelo Conceptual:</strong><ul><li>Importancia del modelado conceptual en el ciclo de vida del software.</li><li>Universo del Discurso y levantamiento de requerimientos de información.</li></ul></li><li><strong>Modelo Entidad-Relación (E/R):</strong><ul><li><strong>Entidades:</strong> Fuertes (regulares) y Débiles. Instancias de entidad.</li><li><strong>Atributos:</strong> Simples, compuestos, monovaluados, multivaluados, derivados y nulos. Claves candidatas y Clave Primaria (PK).</li><li><strong>Relaciones:</strong> Concepto de conjunto de relaciones y grado de una relación (unarias/reflexivas, binarias, ternarias).</li><li><strong>Cardinalidad y Multiplicidad:</strong> Razón de cardinalidad (1:1, 1:N, N:M) y Restricciones de participación (total/obligatoria vs. parcial/opcional).</li><li>Roles en las relaciones y atributos propios en las relaciones.</li></ul></li><li><strong>Modelado Moderno mediante Diagramas de Código (Mermaid <code>erDiagram</code>):</strong><ul><li>Sintaxis nativa en Markdown para documentación viva del software.</li><li>Simbología de cardinalidades (<code>||--||</code>, <code>||--o|</code>, <code>||--o{</code>, <code>||--|{</code>, <code>}o--o{</code>).</li><li>Especificación de atributos, tipos de datos, identificadores <code>PK</code>/<code>FK</code> y comentarios semánticos.</li><li>Resolución conceptual y lógica de relaciones de muchos a muchos (N:M) mediante tablas intermedias.</li></ul></li><li><strong>Extensiones del Modelo E/R (EER):</strong><ul><li>Especialización y Generalización.</li><li>Entidades Supertipo y Subtipo.</li><li>Herencia de atributos y restricciones de disyunción/solapamiento.</li></ul></li></ul><h3 id="unidad-3-el-modelo-de-datos-relacional-y-normalizacion" tabindex="-1">Unidad 3: El modelo de datos relacional y normalización <a class="header-anchor" href="#unidad-3-el-modelo-de-datos-relacional-y-normalizacion" aria-label="Permalink to &quot;Unidad 3: El modelo de datos relacional y normalización&quot;">​</a></h3><ul><li><strong>Fundamentos Matemáticos del Modelo Relacional:</strong><ul><li>Concepto formal de relación matemática y tabla relacional.</li><li>Estructura: Esquemas, Tablas, Tuplas (filas), Atributos (columnas) y Dominios.</li><li>Propiedades formales de las relaciones: Atomicidad de atributos, unicidad de tuplas, orden indiferente.</li></ul></li><li><strong>Reglas de Integridad Relacional:</strong><ul><li>Integridad de Entidad (la clave primaria no puede admitir valores nulos).</li><li>Integridad Referencial (las claves foráneas <code>FK</code> deben coincidir con una clave primaria existente o ser nulas).</li><li>Integridad de Dominio y restricciones semánticas (<code>CHECK</code>, <code>NOT NULL</code>, <code>UNIQUE</code>).</li></ul></li><li><strong>Álgebra Relacional:</strong><ul><li>Operaciones fundamentales: Selección ($\\sigma$), Proyección ($\\pi$), Producto Cartesiano ($\\times$), Unión ($\\cup$), Diferencia ($-$).</li><li>Operaciones derivadas: Reunión Natural / Join ($\\bowtie$), Intersección ($\\cap$), División ($\\div$).</li></ul></li><li><strong>Conversión del Modelo E/R (Mermaid) al Modelo Relacional Físico:</strong><ul><li>Reglas de mapeo de entidades regulares y débiles.</li><li>Reglas de mapeo de relaciones binarias 1:1, 1:N y N:M.</li><li>Mapeo de atributos multivaluados y relaciones de herencia.</li></ul></li><li><strong>Teoría de la Normalización de Bases de Datos:</strong><ul><li>El problema de las redundancias y las anomalías de actualización, inserción y borrado.</li><li>Concepto de Dependencia Funcional (DF) y Clausura de dependencias.</li><li>Primera Forma Normal (1FN): Eliminación de grupos repetitivos y valores atómicos.</li><li>Segunda Forma Normal (2FN): Dependencia funcional completa respecto a la clave primaria.</li><li>Tercera Forma Normal (3FN): Eliminación de dependencias transitivas.</li><li>Forma Normal de Boyce-Codd (BCNF): Todo determinante debe ser una superclave.</li><li>Criterios prácticos de desnormalización controlada para optimización de consultas.</li></ul></li></ul><h3 id="unidad-4-el-lenguaje-de-base-de-datos-sql-ddl-dml-dql-y-transacciones" tabindex="-1">Unidad 4: El lenguaje de base de datos SQL (DDL, DML, DQL y Transacciones) <a class="header-anchor" href="#unidad-4-el-lenguaje-de-base-de-datos-sql-ddl-dml-dql-y-transacciones" aria-label="Permalink to &quot;Unidad 4: El lenguaje de base de datos SQL (DDL, DML, DQL y Transacciones)&quot;">​</a></h3><ul><li><strong>Introducción al Estándar SQL y Motores Abiertos (PostgreSQL / MySQL):</strong><ul><li>Filosofía declarativa del lenguaje SQL.</li><li>Configuración e interacción mediante consola CLI y herramientas gráficas (DBeaver, pgAdmin).</li></ul></li><li><strong>Lenguaje de Definición de Datos (DDL):</strong><ul><li>Creación, modificación y eliminación de bases de datos y tablas (<code>CREATE DATABASE</code>, <code>CREATE TABLE</code>, <code>ALTER TABLE</code>, <code>DROP TABLE</code>, <code>TRUNCATE</code>).</li><li>Definición de tipos de datos: numéricos, cadenas de texto, booleanos, fechas/horas, JSON.</li><li>Implementación de restricciones: <code>PRIMARY KEY</code>, <code>FOREIGN KEY</code> (con acciones referenciales <code>CASCADE</code>, <code>SET NULL</code>, <code>RESTRICT</code>), <code>UNIQUE</code>, <code>NOT NULL</code>, <code>CHECK</code>, <code>DEFAULT</code>.</li></ul></li><li><strong>Lenguaje de Manipulación de Datos (DML):</strong><ul><li>Inserción de datos (<code>INSERT INTO ... VALUES</code>, inserciones masivas).</li><li>Modificación de tuplas (<code>UPDATE ... SET ... WHERE</code>).</li><li>Eliminación de tuplas (<code>DELETE FROM ... WHERE</code>).</li></ul></li><li><strong>Lenguaje de Consulta de Datos (DQL - Data Query Language):</strong><ul><li>Consultas básicas: <code>SELECT</code>, proyecciones, alias (<code>AS</code>), cláusula <code>WHERE</code>, operadores de comparación, lógicos (<code>AND</code>, <code>OR</code>, <code>NOT</code>) y de rango/conjunto (<code>BETWEEN</code>, <code>IN</code>, <code>LIKE</code>, <code>IS NULL</code>).</li><li>Manejo de fechas, cadenas y valores <code>NULL</code> (lógica trivaluada: True, False, Unknown).</li><li>Ordenamiento y paginación (<code>ORDER BY ASC/DESC</code>, <code>LIMIT</code>, <code>OFFSET</code>).</li></ul></li><li><strong>Consultas Multirrelacionales y Agregaciones Avanzadas:</strong><ul><li>Composición de tablas: Producto cartesiano, <code>INNER JOIN</code>, <code>LEFT JOIN</code>, <code>RIGHT JOIN</code>, <code>FULL OUTER JOIN</code>.</li><li>Funciones de agregación: <code>COUNT()</code>, <code>SUM()</code>, <code>AVG()</code>, <code>MIN()</code>, <code>MAX()</code>.</li><li>Agrupamiento de datos: <code>GROUP BY</code> y filtrado de grupos mediante <code>HAVING</code>.</li><li>Operaciones de conjuntos en SQL: <code>UNION</code>, <code>UNION ALL</code>, <code>INTERSECT</code>, <code>EXCEPT</code>.</li><li>Subconsultas: Subconsultas escalares, subconsultas en <code>FROM</code>, operadores correlacionados (<code>IN</code>, <code>EXISTS</code>, <code>ANY</code>, <code>ALL</code>).</li></ul></li></ul><hr><h2 id="🛠️-estrategias-metodologicas-y-pedagogicas" tabindex="-1">🛠️ ESTRATEGIAS METODOLÓGICAS Y PEDAGÓGICAS <a class="header-anchor" href="#🛠️-estrategias-metodologicas-y-pedagogicas" aria-label="Permalink to &quot;🛠️ ESTRATEGIAS METODOLÓGICAS Y PEDAGÓGICAS&quot;">​</a></h2><ol><li><strong>Aprender Haciendo (<em>Learning by Doing</em>):</strong><br> Prácticas continuas de laboratorio conectando teoría y ejecución inmediata en computadoras con motores relacionales libres (<strong>PostgreSQL</strong> y <strong>MySQL</strong>).</li><li><strong>Documentación Viva de Modelos con Mermaid.js:</strong><br> Enseñanza del diseño de esquemas mediante código Markdown usando <code>mermaid</code> (<code>erDiagram</code>), permitiendo que el estudiante versione sus diagramas en Git junto al código fuente del sistema.</li><li><strong>Casos de Estudio Contextualizados:</strong><br> Los ejercicios y proyectos se basan en problemáticas reales de la comunidad y del entorno universitario (Sistemas de Gestión de Pacientes, Control de Estudios, Inventarios y Centros de Diagnóstico Integral - CDI), articulándose directamente con el <strong>Proyecto Sociotecnológico II (PST-II)</strong>.</li><li><strong>Laboratorios Prácticos Anticipados:</strong><br> Guías de cátedra y enunciados de laboratorio entregados con antelación para que el estudiante investigue, proponga soluciones y las defienda en sesión técnica presencial.</li></ol><hr><h2 id="📚-recursos-didacticos-y-de-laboratorio" tabindex="-1">📚 RECURSOS DIDÁCTICOS Y DE LABORATORIO <a class="header-anchor" href="#📚-recursos-didacticos-y-de-laboratorio" aria-label="Permalink to &quot;📚 RECURSOS DIDÁCTICOS Y DE LABORATORIO&quot;">​</a></h2><ul><li><strong>Equipamiento:</strong> Computadores de laboratorio con sistemas operativos libres (GNU/Linux Debian/Ubuntu) o Windows.</li><li><strong>Herramientas de Software:</strong><ul><li>Motores de bases de datos relacionales: PostgreSQL (versión 14+) y MySQL / MariaDB.</li><li>Clientes de administración: DBeaver Community Edition, pgAdmin 4.</li><li>Editores y entornos de diagramación: VS Code / VSCodium con extensiones Mermaid Preview, entornos Markdown.</li></ul></li><li><strong>Material Instruccional:</strong><ul><li>Manuales de estudio profundo por evaluación desarrollados por la cátedra.</li><li>Guía Técnica y Pedagógica de Sintaxis Mermaid ERD.</li><li>Repositorio de código y ejercicios prácticos en Git.</li></ul></li></ul><hr><h2 id="📖-referencias-bibliograficas" tabindex="-1">📖 REFERENCIAS BIBLIOGRÁFICAS <a class="header-anchor" href="#📖-referencias-bibliograficas" aria-label="Permalink to &quot;📖 REFERENCIAS BIBLIOGRÁFICAS&quot;">​</a></h2><ol><li><strong>Date, C. J.</strong> (2001). <em>Introducción a los sistemas de bases de datos</em> (7ª ed.). Prentice Hall / Pearson Educación.</li><li><strong>Elmasri, R., &amp; Navathe, S. B.</strong> (2007). <em>Sistemas de Bases de Datos: Conceptos Fundamentales</em> (5ª ed.). Addison-Wesley Iberoamericana.</li><li><strong>Garcia-Molina, H., Ullman, J. D., &amp; Widom, J.</strong> (2002). <em>Database Systems: The Complete Book</em>. Prentice Hall.</li><li><strong>Kroenke, D. M.</strong> (2003). <em>Procesamiento de Bases de Datos: Fundamentos, Diseño e Implementación</em> (8ª ed.). Pearson Educación / Prentice Hall.</li><li><strong>Silberschatz, A., Korth, H. F., &amp; Sudarshan, S.</strong> (2006). <em>Fundamentos de Bases de Datos</em> (5ª ed.). McGraw-Hill Interamericana.</li><li><strong>Rob, P., &amp; Coronel, C.</strong> (2006). <em>Sistemas de Bases de Datos: Diseño, Implementación y Administración</em> (7ª ed.). Thomson Learning.</li><li><strong>Mermaid.js Official Documentation.</strong> (2026). <em>Entity Relationship Diagrams (<code>erDiagram</code>)</em>. Disponible en: <a href="https://mermaid.js.org/syntax/entityRelationshipDiagram.html" target="_blank" rel="noreferrer">https://mermaid.js.org/syntax/entityRelationshipDiagram.html</a></li><li><strong>Documento Rector del PNFI.</strong> (2010/2014). Ministerio del Poder Popular para la Educación Universitaria, Ciencia y Tecnología (MPPEUCT), Venezuela.</li></ol>',25)])])}const p=a(d,[["render",n]]);export{g as __pageData,p as default};
